package dev.pathland.server;


import dev.pathland.view.core.ThemeData;
import dev.pathland.view.core.View;

/**
 * The application's root-view factory — the single app-specific piece the server
 * runtime needs. A host (Spring Boot / Quarkus starter) provides one as a bean; the
 * runtime mounts a fresh root per session (views hold per-session {@code State}).
 *
 * <pre>{@code
 * @Bean PathlandApp pathlandApp() { return () -> new MyHomeView(); }
 * }</pre>
 */
@FunctionalInterface
public interface PathlandApp {

    /** A fresh root view for a new session. */
    View newRoot();

    /** The optional global theme (design-token overrides); {@code null} for none. */
    default ThemeData theme() {
        return null;
    }

    /**
     * Optional per-route document metadata for the SSR head (canonical URL,
     * Open Graph/Twitter cards, JSON-LD). Called before the first render with
     * the active route, so an app can make metadata route-specific.
     *
     * <p>Returned non-null fields override the host defaults built from the
     * request URL and {@code pathland.seo.*} config. The default returns no
     * overrides.
     */
    default PageMetadata pageMetadata(PageMetadataRequest request) {
        return PageMetadata.empty();
    }
}

package dev.pathland.server;

/**
 * One Pathland application mounted at a subpath prefix. The server runtime hosts any
 * number of these: each gets its own {@link PathlandRegistry}, its own framework base
 * ({@code /<path>/_pathland}), per-app state-store scoping, and its own WebSocket
 * endpoint. {@code "/"} mounts the app at the root (the classic single-app layout).
 *
 * <pre>{@code
 * MountedApp.of("/", rootApp);   // the main app owns every path not claimed by a mount
 * MountedApp.of("/app2", other); // a second app served under /app2/**
 * }</pre>
 *
 * <p>The mount path is normalized (leading slash, no trailing slash). App routes seen by
 * the mounted app are <b>relative to the mount</b>: a request for {@code /app2/home} is
 * routed to the app mounted at {@code /app2} with the route {@code /home}.
 */
public record MountedApp(String path, PathlandApp app) {

    public MountedApp {
        path = normalize(path);
        if (app == null) {
            throw new IllegalArgumentException("MountedApp requires an app");
        }
    }

    public static MountedApp of(String path, PathlandApp app) {
        return new MountedApp(path, app);
    }

    private static String normalize(String path) {
        if (path == null || path.isBlank()) {
            return "/";
        }
        if (!path.startsWith("/")) {
            path = "/" + path;
        }
        while (path.length() > 1 && path.endsWith("/")) {
            path = path.substring(0, path.length() - 1);
        }
        return path;
    }
