        this(DEFAULT_FLUSH_INTERVAL_MILLIS, DEFAULT_MAX_BATCH_BYTES, sender);
    }

    public DeltaBatcher(long flushIntervalMillis, int maxBatchBytes, Consumer<byte[]> sender) {
