         } catch (RuntimeException e) {
             // The actor is shutting down or rejected the task; updates are moot.
             scheduled.set(false);
         }
     }

     /** Actor task: apply every latest value, looping while new updates arrive. */
     private void drain() {
         while (!closed.get()) {
             for (SubscriptionKey key : new ArrayList<>(pending.keySet())) {
                 Pending value = pending.remove(key);
                 if (value != null) {
                     apply(key, value.value());
                 }
             }
             scheduled.set(false);
             if (!pending.isEmpty() && scheduled.compareAndSet(false, true)) {
                 continue;
             }
             return;
         }
         pending.clear();
     }

     @SuppressWarnings("unchecked")
     private void apply(SubscriptionKey key, Object value) {
         WritableSignal<Object> signal = locals.get(key);
         if (signal == null) {
             telemetry.subscriptionDropped(mount, key.topic(), "unsubscribed");
             return;
         }
         try {
             signal.set(value);
         } catch (RuntimeException e) {
             LOG.warn("topic '{}' update failed for subject {}: {}",
                     key.topic(), key.subject(), e.getMessage());
             telemetry.subscriptionDropped(mount, key.topic(), "effect-error");
         }
     }

     /** Stop routing updates to this session and unregister every subscription. */
     void close() {
         if (!closed.compareAndSet(false, true)) {
             return;
         }
         if (hub != null) {
             for (SubscriptionKey key : new ArrayList<>(locals.keySet())) {
                 hub.unsubscribe(key, this);
             }
         }
         locals.clear();
         pending.clear();
         scheduled.set(false);
     }

     /** Whether this session's subscriptions are closed (test hook). */
     boolean isClosed() {
         return closed.get();
     }
+
+    /**
+     * A read-only snapshot of this session's subscriptions. Must run on the
+     * session actor (the local mirror maps are actor-confined). The pending map is
+     * concurrent, so an in-flight publish is reported as pending.
+     */
+    java.util.List<PathlandIntrospection.SubscriptionSnapshot> snapshot() {
+        java.util.List<PathlandIntrospection.SubscriptionSnapshot> result =
+                new java.util.ArrayList<>(locals.size());
+        for (SubscriptionKey key : locals.keySet()) {
+            result.add(new PathlandIntrospection.SubscriptionSnapshot(
+                    key.topic(), String.valueOf(key.subject()), pending.containsKey(key)));
+        }
+        return java.util.List.copyOf(result);
+    }
