import java.net.URI;
import java.net.http.*;
import java.util.concurrent.*;
public class Ws {
  public static void main(String[] a) throws Exception {
    var latch = new CountDownLatch(1);
    var ws = HttpClient.newHttpClient().newWebSocketBuilder().buildAsync(URI.create("ws://localhost:8081/q/dev-ui/json-rpc-ws"), new WebSocket.Listener() {
      public CompletionStage<?> onText(WebSocket w, CharSequence data, boolean last) {
        System.out.println(data); latch.countDown(); return null;
      }
    }).join();
    ws.sendText("{\"jsonrpc\":\"2.0\",\"method\":\"pathland-quarkus_sessions\",\"params\":{},\"id\":1}", true).join();
    latch.await(10, TimeUnit.SECONDS); ws.sendClose(1000, "done"); 
  }
}
