import dev.pathland.server.test.WsSession;
import java.net.URI; java.net.http.*; import java.util.concurrent.*;
public class DevUiProbe {
  public static void main(String[] args) throws Exception {
    try (WsSession app = WsSession.connect("ws://localhost:8081/_pathland/ws", "devui-probe")) {
      app.sendEnvironment(1024, 768, "/");
      app.awaitFrame(f -> true, 5000);
      // Dev UI WS
      CountDownLatch latch = new CountDownLatch(1);
      WebSocket ws = HttpClient.newHttpClient().newWebSocketBuilder().buildAsync(URI.create("ws://localhost:8081/q/dev-ui/json-rpc-ws"), new WebSocket.Listener() {
        public CompletionStage<?> onText(WebSocket w, CharSequence data, boolean last) {
          System.out.println("RPC: " + data);
          if (data.toString().contains("\"id\":7")) latch.countDown();
          return null;
        }
      }).get(5, TimeUnit.SECONDS);
      ws.sendText("{\"jsonrpc\":\"2.0\",\"method\":\"pathland-quarkus_sessions\",\"params\":{},\"id\":7}", true).join();
      latch.await(5, TimeUnit.SECONDS);
      ws.sendClose(1000, "bye");
    }
  }
}
