const targets = await (await fetch('http://localhost:9222/json')).json();
const page = targets.find(t => t.type === 'page' && t.url.includes('/q/dev-ui/'));
if (!page) { console.log('NO PAGE TARGET', targets.map(t=>[t.type,t.url])); process.exit(1); }
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
const expr = `(() => {
  const el = document.querySelector('qwc-pathland-sessions');
  if (!el) return { found: false, body: document.body.innerText.slice(0, 400) };
  const root = el.shadowRoot;
  const grid = root && root.querySelector('vaadin-grid');
  return {
    found: true,
    shadowText: root ? root.textContent.replace(/\\s+/g, ' ').trim().slice(0, 500) : null,
    rows: grid ? grid.items?.length ?? 'unknown' : 'no grid',
    html: root ? root.innerHTML.slice(0, 800) : null
  };
})()`;
ws.send(JSON.stringify({id: 1, method: 'Runtime.evaluate', params: {expression: expr, returnByValue: true, awaitPromise: true}}));
const msg = await new Promise(res => { ws.onmessage = e => res(JSON.parse(e.data)); });
console.log(JSON.stringify(msg.result?.result?.value ?? msg, null, 2));
ws.close();
EOF
