         val ops = ArrayList<Runnable>()
         reconcileNode(old, fresh, ops)
         if (ops.isNotEmpty()) {
             sink.beginFrame()
             for (op in ops) op.run()
             sink.endFrame()
         }
         slot.node = fresh
         val parent = slot.nodeParent
         if (parent != null) {
             parent.children[slot.nodeIndex] = fresh
             linkSlots(fresh, parent, slot.nodeIndex)
