     private fun collectSlotInputs(slot: ViewSlot, enclosing: Router?): Router? {
         var scope = enclosing
         val node = slot.node
         if (node != null) scope = collectOwnedInputs(node, slot, enclosing)
         for (child in slot.children) collectSlotInputs(child, scope)
