public void flush() {
    byte[] encoded;
    int flushedFrames;
    int flushedOpcodes;
    int flushedSequence;
    long nanos;
    synchronized (this) {
        flushScheduled.set(false);
        if (opcodes.isEmpty()) {
            return;
        }
        long start = System.nanoTime();
        ProtocolFrame merged = new ProtocolFrame(List.copyOf(opcodes), strings.toByteArray());
        flushedFrames = frames;
        flushedOpcodes = opcodes.size();
        opcodes.clear();
        strings.reset();
        approxBytes = 0;
        frames = 0;
        // Stamp the batch's per-stream sequence so the client can detect a
        // lost batch (a gap) and recover with META::RESYNC (spec/OPCODE.md
        // §Sequence gap detection). Only non-empty batches consume a number.
        int sequence = nextSequence++;
        encoded = FrameCodec.encodeFrame(merged, sequence);
        nanos = System.nanoTime() - start;
        batchesFlushed++;
        lastSequence = sequence;
        lastFrames = flushedFrames;
        lastOpcodes = flushedOpcodes;
        lastBytes = encoded.length;
        flushedSequence = sequence;
    }
    telemetry.batchFlushed(mount, flushedFrames, flushedOpcodes, encoded.length, nanos);
    if (trace != PathlandDevTrace.NOOP) {
        try {
            trace.batchSent(sessionId, mount, flushedSequence, flushedFrames, encoded);
        } catch (RuntimeException ignored) {
            // a diagnostic observer must never break emission
        }
    }
    sender.accept(encoded);
}

