import { LitElement, html, css } from 'lit';
import '@vaadin/text-field';
import '@vaadin/button';
import '@vaadin/checkbox';
import { notifier } from 'notifier';
import { JsonRpc } from 'jsonrpc';

export class QwcPathlandSsr extends LitElement {

    jsonRpc = new JsonRpc(this);

    static styles = css`
        :host {
            display: flex;
            flex-direction: column;
            gap: 10px;
            height: 100%;
        }
        .toolbar {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 8px 12px 0 12px;
            flex-wrap: wrap;
        }
        .spacer { flex: 1; }
        .muted { color: var(--lumo-contrast-60pct); }
        .error {
            margin: 8px 12px;
            padding: 8px 12px;
            border-radius: var(--lumo-border-radius-m);
            background: var(--lumo-error-color-10pct, #fdecea);
            color: var(--lumo-error-text-color, #c62828);
        }
        .content {
            flex: 1;
            min-height: 0;
            padding: 0 12px 12px 12px;
        }
        iframe {
            width: 100%;
            height: 100%;
            border: 1px solid var(--lumo-contrast-20pct);
            border-radius: var(--lumo-border-radius-m);
            background: white;
        }
        pre {
            margin: 0;
            height: 100%;
            overflow: auto;
            padding: 12px;
            border: 1px solid var(--lumo-contrast-20pct);
            border-radius: var(--lumo-border-radius-m);
            font-family: var(--lumo-monospace-font, monospace);
            font-size: var(--lumo-font-size-s);
            white-space: pre-wrap;
            word-break: break-word;
        }
    `;

    static properties = {
        _mount: { state: true },
        _route: { state: true },
        _html: { state: true },
        _error: { state: true },
        _showSource: { state: true },
        _loading: { state: true }
    };

    constructor() {
        super();
        this._mount = '/';
        this._route = '/';
        this._html = '';
        this._error = null;
        this._showSource = false;
        this._loading = false;
    }

    connectedCallback() {
        super.connectedCallback();
        this._render();
    }

    render() {
        return html`
            <div class="toolbar">
                <vaadin-text-field label="Mount" .value=${this._mount}
                        @value-changed=${(event) => this._mount = event.detail.value}>
                </vaadin-text-field>
                <vaadin-text-field label="Route" .value=${this._route}
                        @value-changed=${(event) => this._route = event.detail.value}>
                </vaadin-text-field>
                <vaadin-button theme="primary" ?disabled=${this._loading} @click=${this._render}>
                    Render
                </vaadin-button>
                <vaadin-checkbox ?checked=${this._showSource}
                        @change=${(event) => this._showSource = event.target.checked}>
                    Source
                </vaadin-checkbox>
                <span class="spacer"></span>
                <span class="muted">${this._html ? this._html.length + ' chars' : ''}</span>
            </div>
            ${this._error ? html`<div class="error">${this._error}</div>` : ''}
            <div class="content">
                ${this._showSource
                    ? html`<pre>${this._html || 'No document rendered yet.'}</pre>`
                    : html`<iframe sandbox="allow-same-origin" .srcdoc=${this._html || ''}></iframe>`}
            </div>
        `;
    }

    _render = () => {
        this._loading = true;
        return this.jsonRpc.ssr({ mount: this._mount, route: this._route })
            .then((response) => {
                const preview = response.result || {};
                this._error = preview.error || null;
                this._html = preview.html || '';
                if (preview.error) {
                    notifier.showErrorMessage('SSR render failed: ' + preview.error);
                }
            })
            .catch((error) => {
                this._error = (error && (error.message || error.error)) || String(error);
            })
            .finally(() => {
                this._loading = false;
            });
    };
}

customElements.define('qwc-pathland-ssr', QwcPathlandSsr);

import { LitElement, html, css } from 'lit';
import '@vaadin/grid';
import '@vaadin/text-field';
import '@vaadin/select';
import { protocol } from 'build-time-data';

export class QwcPathlandProtocol extends LitElement {

    static styles = css`
        :host {
            display: flex;
            flex-direction: column;
            gap: 10px;
            height: 100%;
        }
        .toolbar {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 8px 12px 0 12px;
            flex-wrap: wrap;
        }
        .spacer { flex: 1; }
        .muted { color: var(--lumo-contrast-60pct); }
        vaadin-grid {
            flex: 1;
            min-height: 0;
        }
        .mono {
            font-family: var(--lumo-monospace-font, monospace);
            font-size: var(--lumo-font-size-s);
        }
    `;

    static properties = {
        _query: { state: true },
        _kind: { state: true }
    };

    constructor() {
        super();
        this._query = '';
        this._kind = '';
    }

    render() {
        return html`
            <div class="toolbar">
                <vaadin-text-field placeholder="Search name, group or value" clear-button-visible
                        style="min-width: 320px"
                        @value-changed=${(event) => this._query = event.detail.value}>
                </vaadin-text-field>
                <vaadin-select label="Kind" .items=${this._kindItems()} .value=${this._kind}
                        item-label-path="label" item-value-path="value"
                        @value-changed=${(event) => this._kind = event.detail.value}>
                </vaadin-select>
                <span class="spacer"></span>
                <span class="muted">${this._filtered().length} row(s)</span>
            </div>
            <vaadin-grid .items=${this._filtered()} theme="compact">
                <vaadin-grid-column path="kind" header="Kind" auto-width></vaadin-grid-column>
                <vaadin-grid-column path="group" header="Group" auto-width></vaadin-grid-column>
                <vaadin-grid-column header="Name" auto-width
                        ${this._monoRenderer('name')}></vaadin-grid-column>
                <vaadin-grid-column header="Value" auto-width
                        ${this._monoRenderer('value')}></vaadin-grid-column>
            </vaadin-grid>
        `;
    }

    _monoRenderer(path) {
        return (root, column, model) => {
            root.textContent = model.item[path];
            root.className = 'mono';
        };
    }

    _kindItems() {
        const kinds = Array.from(new Set((protocol || []).map((row) => row.kind))).sort();
        return [{ label: 'All', value: '' }, ...kinds.map((kind) => ({ label: kind, value: kind }))];
    }

    _filtered() {
        const query = (this._query || '').toLowerCase();
        const kind = this._kind;
        return (protocol || []).filter((row) => {
            if (kind && row.kind !== kind) return false;
            if (!query) return true;
            return [row.kind, row.group, row.name, row.value]
                .some((value) => (value || '').toLowerCase().includes(query));
        });
    }
}

customElements.define('qwc-pathland-protocol', QwcPathlandProtocol);

