const ws = new WebSocket('ws://localhost:8081/q/dev-ui/json-rpc-ws');
const timer = setTimeout(() => { console.log('TIMEOUT'); process.exit(1); }, 10000);
ws.onopen = () => ws.send(JSON.stringify({jsonrpc:'2.0', method:'tools_list', params:{}, id:1}));
ws.onmessage = (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id === 1) {
    const text = JSON.stringify(msg, null, 2);
    console.log(text.length > 12000 ? text.slice(0, 12000) + '\n...TRUNCATED...' : text);
    clearTimeout(timer);
    ws.close();
    process.exit(0);
  }
};
ws.onerror = (e) => { console.log('ERROR', e); process.exit(1); };
EOF

